    bind.execute(sa.text("""
        DELETE FROM productos_fitosanitarios WHERE nombre = ANY(:nombres)
        AND id NOT IN (SELECT producto_id FROM precios_productos WHERE tipo = 'referencia')
    """), {"nombres": nombres})
